"""Text-to-SQL harness: grounded drafting + one execution-checked repair.

Contract (fixed): solve(task, env) -> {"sql": str}
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
ANY_SQL = re.compile(r"\bselect\b", re.I)


def extract_sql(text):
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    for b in reversed(blocks):
        if ANY_SQL.search(b):
            return b.rstrip(";").strip()
    # unterminated fence (truncation): take what follows the last opener
    if "```" in text:
        tail = text.rsplit("```", 1)[-1].strip()
        if ANY_SQL.search(tail):
            return tail.rstrip(";").strip()
    m = list(ANY_SQL.finditer(text))
    if m:
        return text[m[-1].start():].strip().rstrip(";").strip()
    return text.strip().rstrip(";").strip()


def _fmt_rows(res, limit=8):
    out = []
    for r in res.get("rows", [])[:limit]:
        out.append(" | ".join("" if v is None else str(v) for v in r))
    return "\n".join(out)


def _needs_review(sql, res):
    """Cheap, generic signals that a draft deserves a second look."""
    if not res.get("ok"):
        return "The query failed to execute."
    if res.get("n_rows", 0) == 0:
        return "The query returned ZERO rows. Most likely a literal value, a value column, or a join/filter is wrong."
    cols = res.get("columns") or []
    low = sql.lower()
    joined = (" join " in low) or (low.count(" from ") and "," in low.split(" where ")[0])
    if joined and len(cols) == 1 and "count(" not in low and "avg(" not in low \
            and "sum(" not in low and "max(" not in low and "min(" not in low:
        return ("The query joins multiple tables but returns only one column. Re-read the question: "
                "if it asks 'which <entities>' with a filter on another table, the expected answer may be "
                "all columns of the joined tables (SELECT *). Otherwise keep the single column.")
    return None


def _probe(env, sql):
    """Sample stored values of columns used in equality/LIKE predicates."""
    notes = []
    for col, val in re.findall(r"([A-Za-z_][\w.]*)\s*(?:=|LIKE|like)\s*'([^']{1,40})'", sql)[:3]:
        bare = col.split(".")[-1]
        tbl = None
        m = re.search(r"\bfrom\s+([A-Za-z_]\w*)", sql, re.I)
        if m:
            tbl = m.group(1)
        if not tbl:
            continue
        q = f'SELECT DISTINCT "{bare}" FROM "{tbl}" LIMIT 12'
        r = env.execute(q, max_rows=12)
        if r.get("ok") and r.get("rows"):
            vals = ", ".join(repr(x[0]) for x in r["rows"])
            notes.append(f"Stored values of {tbl}.{bare} (sample): {vals}")
    return notes


def solve(task, env):
    schema = env.schema(task["db_id"])
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n"
    if desc.strip():
        user += f"\nColumn descriptions:\n{desc.strip()[:2000]}\n"
    user += f"\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    budget = env.config.get("max_tokens", 1200)
    reply = env.chat(messages, max_tokens=budget)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": "SELECT 1"}

    res = env.execute(sql, max_rows=20)
    reason = _needs_review(sql, res)
    if reason is None:
        return {"sql": sql}

    feedback = [f"Your draft was:\n```sql\n{sql}\n```", reason]
    if res.get("ok"):
        feedback.append(
            f"It executed: {res.get('n_rows')} rows, columns {res.get('columns')}.\n"
            f"First rows:\n{_fmt_rows(res)}"
        )
    else:
        feedback.append(f"SQLite error: {res.get('error')}")
    if res.get("ok") and res.get("n_rows", 0) == 0:
        feedback.extend(_probe(env, sql))
    feedback.append(
        "Re-read the question and the schema. Fix the specific problem above; do not change parts that "
        "were already right. Answer with the corrected query in one ```sql block."
    )
    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": "\n\n".join(feedback)})
    try:
        reply2 = env.chat(messages, max_tokens=budget)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    res2 = env.execute(sql2, max_rows=20)
    if not res2.get("ok"):
        return {"sql": sql}
    if res2.get("n_rows", 0) == 0 and res.get("ok") and res.get("n_rows", 0) > 0:
        return {"sql": sql}
    return {"sql": sql2}

proposal.raw:
**Diagnosis.** The dominant failure pattern is *unverified drafts*: the incumbent makes one call and never uses `env.execute`, so wrong literal values (`'Bachelors'` vs stored `'Bachelor'`, title case mismatch), wrong value columns (`degree_summary_name` instead of `degree_summary_code`), inverted quantifiers (`< ANY` → `< MIN` instead of `< MAX`), over-broad projections (1 col where gold returns all joined columns) and empty results all ship unchecked. A second, smaller pattern is degenerate/truncated output (sp1008 answered a different question with an analysis query cut off mid-token at 800 tokens).

**Fix.** (1) Rewrite the system prompt to force exact projection semantics, Spider-style inner joins for "X that has Y", correct ANY/ALL translation, and literal-value discipline; (2) add a draft→execute→repair loop using the second allowed policy call, triggered on errors, zero rows, or a suspiciously narrow projection on a multi-table join, feeding real column names + sample values back; (3) raise the token budget so reasoning plus one SQL block is not truncated.

